451	    /**
452	     * Applies an owner's address to the submitted fields, normalizing it in place into the
453	     * canonical form stored and returned for the owner. This is the single intake step that owns
454	     * how a submitted address becomes an owner's stored address: it delegates every transform to
455	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
456	     * the results back onto {@code ownerFieldsDto}.
457	     *
458	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
459	     * is present the two structured lines are normalized in place and the flat {@code address} is
460	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
461	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
462	     * every rule that later reads {@code address} sees the structured value. When no structured
463	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
464	     * backward compatibility.
465	     *
466	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
467	     * blank after normalization in either form is rejected by the required-field check that
468	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
469	     * list of named intake steps and gives address handling one place to grow.
470	     *
471	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
472	     */
473	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
474	        String line1 = ownerFieldsDto.getAddressLine1();
475	        if (line1 != null && !line1.isBlank()) {
476	            String normalizedLine1 = normalizeAddress(line1);
477	            ownerFieldsDto.setAddressLine1(normalizedLine1);
478	            String line2 = ownerFieldsDto.getAddressLine2();
479	            if (line2 != null && !line2.isBlank()) {
480	                String normalizedLine2 = normalizeAddress(line2);
481	                ownerFieldsDto.setAddressLine2(normalizedLine2);
482	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
483	            } else {
484	                ownerFieldsDto.setAddressLine2(null);
485	                ownerFieldsDto.setAddress(normalizedLine1);
486	            }
487	        } else {
488	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
