525	    /**
526	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
527	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
528	     * date already on such a business day is returned unchanged.
529	     *
530	     * @param date the date to adjust
531	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
532	     */
533	    private LocalDate toBusinessDay(LocalDate date) {
534	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
535	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
536	                || PUBLIC_HOLIDAYS.contains(date)) {
537	            date = date.plusDays(1);
538	        }
539	        return date;
540	    }
