246	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
247	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
